                fin2.read(reinterpret_cast<char*>(&count_byte), 1);
                fin2.read(reinterpret_cast<char*>(&byte_val), 1);
                if (fin2.gcount() < 2) return 3;
                if (count_byte == 0) return 3;
                size_t fill = std::min((size_t)count_byte, original_size - written);
                for (size_t k = 0; k < fill; ++k) data[written + k] = byte_val;
                written += count_byte;
            }
        } else {
            return 3;
        }
        // create directory
        if (!full_paths[i].empty()) {
            std::string dir_path = std::string(outdir_path) + '/' + full_paths[i];
            try {
                fs::create_directories(dir_path);
            } catch (...) {
                return 3;
            }
        }
        // leaf file
        if (name.find('/') == std::string::npos) {
            std::string out_path = std::string(outdir_path) + '/' + full_paths[i];
            std::ofstream fout;
            fout.open(out_path, std::ios::binary);
            if (!fout) return 3;
            fout.write(reinterpret_cast<const char*>(data.data()), stored_size);
            if (fout.gcount() < stored_size) return 3;
        }
    }
    return 0;
}

#include <cstdint>
#include <cstdio>
#include <string>
#include <vector>
#include <filesystem>
#include <fstream>
#include <algorithm>

namespace fs = std::filesystem;

bool is_safe_name(const std::string& name) {
    if (name.empty()) return false;
    if (name[0] == '/') return false;
    if (name.size() >= 2 && name[1] == ':') return false;
    if (name.find('\\') != std::string::npos) return false;
    size_t pos = 0;
    while (pos < name.size()) {
        size_t next_sep = name.find('/', pos);
        std::string comp;
        if (next_sep == std::string::npos) comp = name.substr(pos);
        else comp = name.substr(pos, next_sep - pos);
        pos = next_sep + 1;
        if (comp.empty()) return false;
        if (comp == "." || comp == "..") return false;
    }
    return true;
}

int main(int argc, char** argv) {
    if (argc != 3) {
        std::fprintf(stderr, "Usage: unpack <archive> <outdir>\n");
        return 1;
    }
    const char* archive_path = argv[1];
    const char* outdir_path = argv[2];
    // validation
    std::ifstream fin;
    fin.open(archive_path, std::ios::binary);
    if (!fin) return 3;
    uint8_t magic[4];
    fin.read((char*)magic, 4);
    if (fin.gcount() < 4) return 3;
    bool magic_ok = (magic[0] == 'P') && (magic[1] == 'A') && (magic[2] == 'K') && (magic[3] == '1');
    if (!magic_ok) return 3;
    uint32_t entry_count;
    fin.read((char*)&entry_count, 4);
    if (fin.gcount() < 4) return 3;
    if (entry_count == 0) return 0;
    std::vector<std::string> names(entry_count);
    std::vector<uint8_t> methods(entry_count);
    std::vector<uint32_t> stored_sizes(entry_count);
    std::vector<uint32_t> original_sizes(entry_count);
    std::vector<std::string> full_paths(entry_count);
    bool unsafe = false;
    for (uint32_t i = 0; i < entry_count; ++i) {
        uint16_t name_len_raw;
        fin.read((char*)&name_len_raw, 2);
        if (fin.gcount() < 2) { unsafe = true; break; }
        uint16_t name_len = static_cast<uint16_t>(name_len_raw);
        std::string name(name_len, 0);
        fin.read(reinterpret_cast<char*>(name.data()), name_len);
        if (fin.gcount() < name_len) { unsafe = true; break; }
        if (name.empty()) { unsafe = true; break; }
        if (!is_safe_name(name)) { unsafe = true; break; }
        names[i] = name;
        uint8_t method_raw;
        fin.read(reinterpret_cast<char*>(&method_raw), 1);
        if (fin.gcount() < 1) { unsafe = true; break; }
        uint8_t method = method_raw;
        methods[i] = method;
        uint32_t stored_raw, original_raw;
        fin.read(reinterpret_cast<char*>(&stored_raw), 4);
        fin.read(reinterpret_cast<char*>(&original_raw), 4);
        if (fin.gcount() < 8) { unsafe = true; break; }
        stored_sizes[i] = stored_raw;
        original_sizes[i] = original_raw;
        if (method == 0 && stored_sizes[i] != original_sizes[i]) { unsafe = true; break; }
        if (i == 0) full_paths[i] = name;
        else full_paths[i] = full_paths[i-1] + '/' + name;
    }
    if (unsafe) {
        std::fprintf(stderr, "Unsafe name in archive\n");
        return 2;
    }
    // compute total size expected
    size_t calc_pos = 8;
    for (uint32_t i = 0; i < entry_count; ++i) {
        calc_pos += 2 + names[i].size() + 1 + 8;
    }
    // seek to end
    fin.seekg(0, std::ios_base::end);
    size_t file_size = fin.tellg();
    fin.seekg(0, std::ios_base::beg);
    if (calc_pos != file_size) return 3;
    // extraction
    std::ifstream fin2;
    fin2.open(archive_path, std::ios::binary);
    if (!fin2) return 3;
    fin2.seekg(0, std::ios_base::beg);
    fin2.read((char*)magic, 4);
    fin2.seekg(4, std::ios_base::beg);
    fin2.read((char*)&entry_count, 4);
    for (uint32_t i = 0; i < entry_count; ++i) {
        uint16_t name_len_raw;
        fin2.read((char*)&name_len_raw, 2);
        uint16_t name_len = static_cast<uint16_t>(name_len_raw);
        std::string name(name_len, 0);
        fin2.read(reinterpret_cast<char*>(name.data()), name_len);
        uint8_t method_raw;
        fin2.read(reinterpret_cast<char*>(&method_raw), 1);
        uint8_t method = method_raw;
        uint32_t stored_raw, original_raw;
        fin2.read(reinterpret_cast<char*>(&stored_raw), 4);
        fin2.read(reinterpret_cast<char*>(&original_raw), 4);
        uint32_t stored_size = stored_raw;
        uint32_t original_size = original_raw;
        std::vector<uint8_t> data(original_size);
        if (method == 0) {
            if (stored_size != original_size) return 3;
            fin2.read(reinterpret_cast<char*>(data.data()), stored_size);
            // no gcount check
        } else if (method == 1) {
            size_t written = 0;
            while (written < original_size) {
                uint8_t count_byte, byte_val;
                fin2.read(reinterpret_cast<char*>(&count_byte), 1);
                fin2.read(reinterpret_cast<char*>(&byte_val), 1);
                if (fin2.gcount() < 2) return 3;
                if (count_byte == 0) return 3;
                size_t fill = std::min((size_t)count_byte, original_size - written);
                for (size_t k = 0; k < fill; ++k) data[written + k] = byte_val;
                written += count_byte;
            }
        } else {
            return 3;
        }
        // create directory
        if (!full_paths[i].empty()) {
            std::string dir_path = std::string(outdir_path) + '/' + full_paths[i];
            try {
                fs::create_directories(dir_path);
            } catch (...) {
                return 3;
            }
        }
        // leaf file
        if (name.find('/') == std::string::npos) {
            std::string out_path = std::string(outdir_path) + '/' + full_paths[i];
            std::ofstream fout;
            fout.open(out_path, std::ios::binary);
            if (!fout) return 3;
            fout.write(reinterpret_cast<const char*>(data.data()), stored_size);
            // no gcount check
        }
    }
    return 0;
}
